"""Build a bounded job for the standalone namespace, using retained CPU runtime."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--name',required=True);p.add_argument('--command',required=True);p.add_argument('--source',default='microservice-source-v1');p.add_argument('--cpu',default='2400m');p.add_argument('--memory',default='4Gi');p.add_argument('--role',default='runner',choices=['runner','agent','trainer']);a=p.parse_args()
work='/results/'+a.name+'-work'
script=f'mkdir -p {work}\ntar xzf /source/app.tar.gz -C {work}\ncd {work}\nexport PYTHONPATH={work}:{work}/deps:/results/work/upstream\nexport DREAMER_SOURCE=/results/work/upstream\n'+a.command
sec={'allowPrivilegeEscalation':False,'readOnlyRootFilesystem':True,'capabilities':{'drop':['ALL']}}
d={'apiVersion':'batch/v1','kind':'Job','metadata':{'name':a.name,'namespace':'systems-world-model-lab'},'spec':{'backoffLimit':0,'activeDeadlineSeconds':7200,'template':{'metadata':{'labels':{'swm-role':a.role}},'spec':{'restartPolicy':'Never','automountServiceAccountToken':False,'nodeSelector':{'kubernetes.io/hostname':'amd-halo'},'securityContext':{'runAsNonRoot':True,'runAsUser':1000,'runAsGroup':1000,'fsGroup':1000,'seccompProfile':{'type':'RuntimeDefault'}},'containers':[{'name':'experiment','image':'python:3.11-slim','securityContext':sec,'resources':{'requests':{'cpu':'500m','memory':'512Mi'},'limits':{'cpu':a.cpu,'memory':a.memory}},'env':[{'name':'PYTHONUNBUFFERED','value':'1'},{'name':'PYTHONDONTWRITEBYTECODE','value':'1'},{'name':'OMP_NUM_THREADS','value':'1'},{'name':'OPENBLAS_NUM_THREADS','value':'1'},{'name':'XLA_FLAGS','value':'--xla_cpu_multi_thread_eigen=false intra_op_parallelism_threads=1'},{'name':'XDG_CACHE_HOME','value':'/tmp/cache'}],'command':['sh','-ec',script],'volumeMounts':[{'name':'source','mountPath':'/source','readOnly':True},{'name':'results','mountPath':'/results'},{'name':'tmp','mountPath':'/tmp'}]}],'volumes':[{'name':'source','configMap':{'name':a.source}},{'name':'results','persistentVolumeClaim':{'claimName':'results'}},{'name':'tmp','emptyDir':{'sizeLimit':'512Mi'}}]}}}}
path=Path('deploy')/(a.name+'.json');path.write_text(json.dumps(d,indent=2)+'\n');print(path)
